test=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
R,C=len(test),len(test[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if test[r][c]==0 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and test[a][b]==0 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
   comps.append(comp)
[(i,len(x),(min(a for a,b in x),max(a for a,b in x),min(b for a,b in x),max(b for a,b in x)), x) for i,x in enumerate(comps)]
